-- Optional Mechanic content is absent from historical spell-only installations.
WITH expected AS (SELECT value AS entry FROM jsonb_array_elements($entries$[{"id": 59580, "name": "Maneuvering Mines", "description": "Your mines push or pull creatures away from them. You gain the following new mods.\n\n- **Big Bang (mine exocortex):** Your mines blow enemies away. Creatures that fail their saving throw against the mine are pushed 5 feet directly away from the mine (or pushed 10 feet directly away from the mine and knocked prone on a critical failure). This is forced movement.\n- **Black Hole (mine exocortex):** Your mines harness gravity-bending technology. Creatures that fail their saving throw against the mine are pulled 5 feet toward the mine (or pulled 10 feet toward the mine and slowed 1 on a critical failure). This is forced movement.", "operation": {"id": "39ac8a40-bc4a-40d4-a8de-50e3b4a8f4a1", "type": "injectText", "data": {"type": "feat", "id": 59021, "text": "**Maneuvering Mines**\n\nYour mines push or pull creatures away from them. You gain the following new mods.\n\n- **Big Bang (mine exocortex):** Your mines blow enemies away. Creatures that fail their saving throw against the mine are pushed 5 feet directly away from the mine (or pushed 10 feet directly away from the mine and knocked prone on a critical failure). This is forced movement.\n- **Black Hole (mine exocortex):** Your mines harness gravity-bending technology. Creatures that fail their saving throw against the mine are pulled 5 feet toward the mine (or pulled 10 feet toward the mine and slowed 1 on a critical failure). This is forced movement."}}}, {"id": 59691, "name": "Healing Mines", "description": "You've designed a mine that explodes with healing medicine. You gain the following new mod.\n\n**Healing Mines (mine exocortex):** Your mine uses tiny four-sided syringes full of concentrated medicine. Instead of dealing damage, your healing mine causes creatures to regain a number of Hit Points equal to the mine's number of damage dice. Unlike your usual mines, creatures in the area don't attempt a saving throw. At 8th level, add your Intelligence modifier to the number of Hit Points regained.", "operation": {"id": "e1b1f163-1d53-44ff-8f73-0bf5187e5c2a", "type": "injectText", "data": {"type": "feat", "id": 59021, "text": "**Healing Mines**\n\nYou've designed a mine that explodes with healing medicine. You gain the following new mod.\n\n**Healing Mines (mine exocortex):** Your mine uses tiny four-sided syringes full of concentrated medicine. Instead of dealing damage, your healing mine causes creatures to regain a number of Hit Points equal to the mine's number of damage dice. Unlike your usual mines, creatures in the area don't attempt a saving throw. At 8th level, add your Intelligence modifier to the number of Hit Points regained."}}}]$entries$::jsonb)), present AS (
 SELECT 1 FROM public.ability_block WHERE content_source_id = 900 AND id IN (59021,59580,59691)
)
SELECT 'mine-mod-rules' AS id,
 NOT EXISTS (SELECT 1 FROM present) OR (
   (SELECT count(*) FROM expected e JOIN public.ability_block a ON a.id=(e.entry->>'id')::bigint
    WHERE a.content_source_id=900 AND a.name=e.entry->>'name'
      AND a.description=e.entry->>'description'
      AND to_jsonb(a.operations)=jsonb_build_array(e.entry->'operation'))=2
   AND EXISTS (SELECT 1 FROM public.ability_block WHERE id=59021 AND content_source_id=900 AND name='Modify')
   AND NOT EXISTS (SELECT 1 FROM public.content_update WHERE ref_id IN (59580,59691) AND type='ability-block'
      AND (status->>'state' IS NULL OR status->>'state' NOT IN ('APPROVED','REJECTED')))
 ) AS passed;
